const course: DeepCourse = {"slug":"video-editing","title":"Video Editing for Short Form","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section id=\"the-job\" class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Career skill · Pro</p><h1 class=\"display-lg mt-4\">Video Editing for Short Form<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Build fast, watchable short-form edits and a delivery system clients can trust with their raw footage.</p><div class=\"mt-8 flex flex-wrap gap-2.5\"><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold bg-accent-soft text-accent-deep border-transparent\">8 modules</span><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold border\">6-question quiz</span></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">Short-form video is where brands are spending, and they need editors who understand pace, hooks and captions. This course teaches the CapCut and Premiere workflow from raw footage to delivered reel.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You watch reels thinking ‘I could cut this better’. Patience with footage required; fancy gear not.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A start-to-finish editing workflow, a hook-and-caption playbook, and a delivery system clients trust with their raw files.</p></div></div></div></div></section>"},{"kind":"html","value":"<section id=\"the-job\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto grid max-w-5xl gap-10 md:grid-cols-2\"><div><p class=\"eyebrow\">The job</p><h2>The edit is an attention system.</h2><p>A video editing VA turns raw talking-head, podcast, product, and UGC footage into a clip that earns the next second of attention. The client pays for judgment about what to cut, what to show, what to caption, and what to leave alone.</p></div><div><p class=\"eyebrow\">The work</p><p>You will ingest files, find selects, build a rough cut, shape pacing, caption accurately, add sound and b-roll with restraint, export platform-safe versions, collect timecoded feedback, and preserve versions.</p><p>The useful advantage is reliability under volume. A beautiful edit that cannot be found, revised, or delivered in 48 hours is not an agency workflow.</p></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://www.capcut.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">CapCut</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Free editor with official tutorials — the tool in most short-form job ads.</p></a></li><li class=\"h-full\"><a href=\"https://helpx.adobe.com/premiere-pro/tutorials.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Premiere Pro tutorials</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Adobe’s official free lessons for the step-up tool.</p></a></li><li class=\"h-full\"><a href=\"https://www.youtube.com/creators/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">YouTube for Creators</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">How the platform itself says retention and packaging work.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section id=\"tools\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Tools</p><h2>Learn the stack. Do not worship it.</h2><p>CapCut is fast for short form. Premiere Pro and DaVinci Resolve offer deeper control. Frame.io, Google Drive, and a tracker make review survivable. Learn the tool your client uses, but make your naming and review process tool-independent.</p><div class=\"grid gap-4 md:grid-cols-3\"><div class=\"rounded-2xl border p-5\"><h3>CapCut</h3><p>Fast vertical edits, captions, templates, and social-first exports.</p></div><div class=\"rounded-2xl border p-5\"><h3>Premiere Pro</h3><p>Shared project structure, reusable graphics, proxies, and Adobe ecosystem work.</p></div><div class=\"rounded-2xl border p-5\"><h3>Frame.io / Drive</h3><p>Timecoded comments and a review trail that stops “make it better” feedback.</p></div></div></div></section>"},{"kind":"html","value":"<section id=\"rates\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Rates</p><h2>Price the outcome and the risk.</h2><p>New remote short-form work commonly appears around US$10–20 per hour or US$15–60 per simple clip. Rates rise with raw-footage organization, ad editing, motion graphics, thumbnails, long-form work, proof of retention, and reliable volume. Quote a pilot after timing your actual workflow.</p><p>A 30-second clip can take 20 minutes or four hours. Price according to raw footage length, captioning, b-roll, motion, source quality, versions, turnaround, and revision rounds—not final runtime.</p></div></section>"},{"kind":"html","value":"<section id=\"first-client\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">First client</p><h2>Make a small, believable promise.</h2><p>Make five clips from a permitted source. Put the raw timestamp, hook, final export, caption style, and one sentence about the editing choice beside each. A portfolio should show the before-and-after decision, not only the prettiest frame.</p><ol><li>Choose a talk or your own footage you are allowed to edit.</li><li>Mark self-contained moments before opening the editor.</li><li>Deliver five clips with a consistent naming system and review link.</li></ol></div></section>"},{"kind":"html","value":"<section id=\"tools\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Red flags</p><h2>Walk away early.</h2><div class=\"grid gap-4 md:grid-cols-2\"><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Unlimited edits for one clip price</h3><p>Revisions need a number and feedback needs timecodes. Otherwise “small changes” can replace the whole concept.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>“Viral guaranteed”</h3><p>No editor can promise distribution. Promise a tested hook, clear story, and clean platform delivery.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Raw footage in random links</h3><p>Require one source folder and a delivery deadline. Hunting files is billable production work.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Copyright-free means “download anything”</h3><p>Music, stock, and b-roll still need a license that covers the client’s use.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Same rate for 9:16 and 16:9</h3><p>Different formats often mean different framing, captions, and graphics. Scope versions.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>No approver</h3><p>A team that cannot name final approval sends edits in circles.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Password sharing</h3><p>Use client-owned access and approved transfer tools; do not take ownership of accounts.</p></div></div></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"html","value":"<section class=\"px-5 py-20 md:px-8\"><div class=\"mx-auto max-w-5xl rounded-3xl bg-ink p-8 text-paper md:p-12\"><p class=\"eyebrow\">Your next move</p><h2>Do one real video editing va task this week.</h2><p>Make one clean five-clip batch this week. Time every stage, save the project, and watch every final export on a phone. That process is the beginning of a professional editing service.</p><a class=\"button\" href=\"/courses\">Build your proof</a></div></section>"}],"modules":[{"n":1,"title":"Find the hook before the timeline","outcome":"Choose the opening that earns the next two seconds.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Choose the opening that earns the next two seconds.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Short-form viewers decide before an introduction finishes. Watch the source once, mark the strongest promise, proof, surprise, or movement, then cut from that moment.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use markers, a transcript, and a selects sequence before adding effects.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A coach begins a 12-minute video with two minutes of welcome before explaining a common mistake.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You start with “This is why your sales calls die in minute three,” show the coach’s proof, then provide the missing context in one sentence. The hook is honest because the clip delivers it.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Watch raw footage once.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Mark five self-contained moments.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build a plain rough cut around the strongest opening.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Find the hook before the timeline”. The honest answer is:","options":["Create captions that are readable, true, and platform-safe.","Remove friction without making people sound inhuman.","Choose the opening that earns the next two seconds.","Support the story instead of decorating every second."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["You can run an AI-assisted content pipeline a client can trust, with the fact-check built in rather than promised.","Find complete ideas rather than dramatic fragments.","Make feedback precise and finishable.","Support the story instead of decorating every second."],"answer":0,"explain":"That one is from “AI Marketing & AEO”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Find the hook before the timeline”, what do you do first?","options":["Mark five self-contained moments.","Build a plain rough cut around the strongest opening.","Watch raw footage once."],"answer":2,"explain":"Order protects the outcome here: “Watch raw footage once.” comes before everything else, or the rest is guesswork."}]},{"n":2,"title":"Cut for comprehension and retention","outcome":"Remove friction without making people sound inhuman.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Remove friction without making people sound inhuman.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pacing is not random jump cuts. Remove throat-clearing, repeated points, dead air, and context the viewer does not need; keep breaths and pauses that carry meaning.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use J/L cuts, ripple edits, and a muted playback check.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A speaker repeats the same lesson three times in different words.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You keep the clearest version, add one visual change at the shift, and leave a small pause before the instruction. The viewer gets speed without feeling pushed.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Cut the head aggressively.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Check every edit for lost meaning.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Watch once muted.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Cut for comprehension and retention” is building toward?","options":["Turn repeatable edits into a production line.","Remove friction without making people sound inhuman.","Choose the opening that earns the next two seconds.","Hand off clean exports, source files, and useful data."],"answer":1,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Create captions that are readable, true, and platform-safe.","Make feedback precise and finishable.","Hand off clean exports, source files, and useful data.","Turn interest into an honest meeting"],"answer":3,"explain":"That one is from “Sales & Lead Generation VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Cut for comprehension and retention”, what do you do first?","options":["Cut the head aggressively.","Check every edit for lost meaning.","Watch once muted."],"answer":0,"explain":"Order protects the outcome here: “Cut the head aggressively.” comes before everything else, or the rest is guesswork."}]},{"n":3,"title":"Caption accurately and design for a phone","outcome":"Create captions that are readable, true, and platform-safe.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Create captions that are readable, true, and platform-safe.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Auto captions are a draft. Names, numbers, product terms, and negations are where they fail. Caption style should aid reading, not compete with the speaker.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a saved caption style, safe-area guide, and manual transcript review.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A clip says “fifteen percent,” but the auto caption writes “fifty percent.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You correct it, place two short lines above the platform controls, and highlight only the phrase that changes the viewer’s decision. Accuracy is part of brand safety.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Generate captions.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Check names and numbers against audio.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Test on a phone-size preview.</span></label></li></ul></div>","quiz":[{"q":"You just finished “Caption accurately and design for a phone”. What should you now be able to do?","options":["Create captions that are readable, true, and platform-safe.","Find complete ideas rather than dramatic fragments.","Choose the opening that earns the next two seconds.","Hand off clean exports, source files, and useful data."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["You can turn one idea into five platform-native posts without copy-pasting the same caption everywhere.","Find complete ideas rather than dramatic fragments.","Turn repeatable edits into a production line.","Make feedback precise and finishable."],"answer":0,"explain":"That one is from “Social Media Manager VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Caption accurately and design for a phone”, what do you do first?","options":["Generate captions.","Test on a phone-size preview.","Check names and numbers against audio."],"answer":0,"explain":"Order protects the outcome here: “Generate captions.” comes before everything else, or the rest is guesswork."}]},{"n":4,"title":"Use audio, b-roll, and motion with restraint","outcome":"Support the story instead of decorating every second.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Support the story instead of decorating every second.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Music, sound effects, b-roll, zooms, and motion should clarify a shift, proof point, or emotional beat. If removing an effect changes nothing, it is visual noise.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use licensed libraries, audio meters, and a simple b-roll source log.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A presenter describes a confusing dashboard.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You show the dashboard at the exact sentence that names it, lower music under the explanation, and use one subtle zoom to direct the eye. You do not cover the speaker every two seconds.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Mix speech before music.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use b-roll to explain a specific phrase.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Record license or source details.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Use audio, b-roll, and motion with restraint”. The honest answer is:","options":["Turn repeatable edits into a production line.","Hand off clean exports, source files, and useful data.","Support the story instead of decorating every second.","Remove friction without making people sound inhuman."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Find complete ideas rather than dramatic fragments.","You can explain to a client which of their marketing tasks AI genuinely speeds up, which it quietly ruins, and where you fit.","Turn repeatable edits into a production line.","Remove friction without making people sound inhuman."],"answer":1,"explain":"That one is from “AI Marketing & AEO”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Use audio, b-roll, and motion with restraint”, what do you do first?","options":["Mix speech before music.","Record license or source details.","Use b-roll to explain a specific phrase."],"answer":0,"explain":"Order protects the outcome here: “Mix speech before music.” comes before everything else, or the rest is guesswork."}]},{"n":5,"title":"Build templates and batch a week of clips","outcome":"Turn repeatable edits into a production line.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Turn repeatable edits into a production line.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Batch by stage: ingest, selects, rough cuts, captions, polish, export, review. A reusable project template protects consistency and reveals your real capacity.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use bins, sequence naming, proxies, presets, and a delivery tracker.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — You need 20 clips from four episodes.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You create a master project, duplicate sequences, make all rough cuts first, then caption the accepted cuts in one session. When the client changes a caption style, you update one saved style instead of twenty files.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Create a master project.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Time each stage across five clips.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Save presets only after review approval.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Build templates and batch a week of clips” is building toward?","options":["Find complete ideas rather than dramatic fragments.","Choose the opening that earns the next two seconds.","Turn repeatable edits into a production line.","Make feedback precise and finishable."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Find complete ideas rather than dramatic fragments.","Create captions that are readable, true, and platform-safe.","Plan dates people can use","Make feedback precise and finishable."],"answer":2,"explain":"That one is from “Project Management VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Build templates and batch a week of clips”, what do you do first?","options":["Save presets only after review approval.","Create a master project.","Time each stage across five clips."],"answer":1,"explain":"Order protects the outcome here: “Create a master project.” comes before everything else, or the rest is guesswork."}]},{"n":6,"title":"Repurpose long-form without stripping context","outcome":"Find complete ideas rather than dramatic fragments.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Find complete ideas rather than dramatic fragments.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Good repurposing adds enough setup for someone who never saw the source. Preserve the original timecode so the client can review a quote in context.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a transcript search, clip log, and a source-to-export map.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A podcast guest says “that is the problem” after seven minutes of setup.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You either include the missing premise in text or reject the moment. A dramatic line without a complete idea produces comments, not trust.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Mark source timecodes.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write one-sentence context per clip.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Offer fewer strong clips when the source is thin.</span></label></li></ul></div>","quiz":[{"q":"You just finished “Repurpose long-form without stripping context”. What should you now be able to do?","options":["Make feedback precise and finishable.","Create captions that are readable, true, and platform-safe.","Find complete ideas rather than dramatic fragments.","Turn repeatable edits into a production line."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Standardise data while keeping an auditable route back to the source and every important transformation.","Choose the opening that earns the next two seconds.","Remove friction without making people sound inhuman.","Create captions that are readable, true, and platform-safe."],"answer":0,"explain":"That one is from “Data Entry & Research VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Repurpose long-form without stripping context”, what do you do first?","options":["Offer fewer strong clips when the source is thin.","Write one-sentence context per clip.","Mark source timecodes."],"answer":2,"explain":"Order protects the outcome here: “Mark source timecodes.” comes before everything else, or the rest is guesswork."}]},{"n":7,"title":"Manage review, versions, and revisions","outcome":"Make feedback precise and finishable.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Make feedback precise and finishable.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Version control is client care. One review link, named exports, timecoded comments, and a written revision limit protect both speed and goodwill.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use Frame.io or a shared folder with v1, v2, approved naming.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A client says “the middle feels off.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You ask for a timecode and offer two concrete alternatives. The client chooses one, you name the v2 export, and you retain v1. No one has to remember what changed.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Agree revision rounds.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Request timecoded feedback.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never overwrite a reviewed export.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Manage review, versions, and revisions”. The honest answer is:","options":["Create captions that are readable, true, and platform-safe.","Make feedback precise and finishable.","Find complete ideas rather than dramatic fragments.","Remove friction without making people sound inhuman."],"answer":1,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Remove friction without making people sound inhuman.","Support the story instead of decorating every second.","Choose the opening that earns the next two seconds.","Build audiences around a real difference in message, offer, or timing rather than a collection of clever filters."],"answer":3,"explain":"That one is from “Email Marketing VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Manage review, versions, and revisions”, what do you do first?","options":["Agree revision rounds.","Never overwrite a reviewed export.","Request timecoded feedback."],"answer":0,"explain":"Order protects the outcome here: “Agree revision rounds.” comes before everything else, or the rest is guesswork."}]},{"n":8,"title":"Deliver files clients can use next month","outcome":"Hand off clean exports, source files, and useful data.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Hand off clean exports, source files, and useful data.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Delivery includes aspect ratio, resolution, frame rate, captions, thumbnail, copy, project retention, and where the final lives. The file is only one part of the asset.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a delivery checklist and client-owned folder structure.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — An agency requests a vertical Reel, a square ad variant, and clean captions.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You confirm each deliverable, export separate named files, include a short delivery note, and retain the project under the agreed policy. The agency can publish without asking you what “final” means.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Confirm format before editing.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Watch exported files on a phone.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Send a delivery note with versions and next step.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Deliver files clients can use next month” is building toward?","options":["Make feedback precise and finishable.","Hand off clean exports, source files, and useful data.","Remove friction without making people sound inhuman.","Create captions that are readable, true, and platform-safe."],"answer":1,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Create a simple account structure that supports reporting.","Find complete ideas rather than dramatic fragments.","Turn repeatable edits into a production line.","Support the story instead of decorating every second."],"answer":0,"explain":"That one is from “Bookkeeping Basics (Xero & QBO)”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Deliver files clients can use next month”, what do you do first?","options":["Confirm format before editing.","Send a delivery note with versions and next step.","Watch exported files on a phone."],"answer":0,"explain":"Order protects the outcome here: “Confirm format before editing.” comes before everything else, or the rest is guesswork."}]}],"quiz":[{"q":"What should a short-form hook do?","options":["Introduce the editor","Make staying worthwhile immediately","Show every brand logo","Explain all context first"],"answer":1,"explain":"The opening earns attention; context follows only if needed."},{"q":"Why review auto captions manually?","options":["They are always useless","Names and numbers can change the meaning","It increases file size","Platforms reject them"],"answer":1,"explain":"A confident caption error is a brand and accuracy problem."},{"q":"What is the efficient batch sequence?","options":["Finish one clip at a time","Batch by production stage","Export before captions","Choose random clips"],"answer":1,"explain":"Stage batching reduces context switching and supports consistent templates."},{"q":"What makes a repurposed clip safe?","options":["A dramatic sentence","A self-contained idea with enough context","More effects","A longer runtime"],"answer":1,"explain":"A viewer must understand it without the original episode."},{"q":"How should feedback arrive?","options":["As “make it better”","With timecodes and a named approver","Only by voice note","After publishing"],"answer":1,"explain":"Specific feedback makes revisions finite."},{"q":"What changes a clip price most?","options":["Final seconds alone","Raw footage, complexity, versions, and revisions","The editor’s favorite tool","Number of emojis"],"answer":1,"explain":"Scope determines editing time and risk."}],"glossary":[{"term":"Hook","def":"The opening that gives a viewer a reason to continue."},{"term":"Rough cut","def":"The structural edit before polish and effects."},{"term":"B-roll","def":"Supporting visual footage used to clarify or vary a scene."},{"term":"J-cut","def":"Audio from the next shot begins before the picture changes."},{"term":"L-cut","def":"Audio continues after the picture changes."},{"term":"Safe area","def":"The part of a frame not covered by a platform interface."},{"term":"Proxy","def":"A lighter copy used to edit high-resolution footage smoothly."},{"term":"Frame rate","def":"The number of frames displayed each second."},{"term":"Codec","def":"The compression format used to encode video."},{"term":"Timecode","def":"A precise timestamp used to locate a moment."},{"term":"Burned captions","def":"Captions embedded in the video image."},{"term":"Color grade","def":"A deliberate visual adjustment beyond basic correction."}]};

export default course;
